import{_ as e,c as a,o as i,ae as o}from"./chunks/framework.CBTkueSR.js";const d=JSON.parse('{"title":"GoCommit Documentation","description":"","frontmatter":{},"headers":[],"relativePath":"README.md","filePath":"README.md"}'),r={name:"README.md"};function n(l,t,s,u,h,m){return i(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="gocommit-documentation" tabindex="-1">GoCommit Documentation <a class="header-anchor" href="#gocommit-documentation" aria-label="Permalink to &quot;GoCommit Documentation&quot;">​</a></h1><p>Welcome to the GoCommit documentation! This collection provides comprehensive guides for using and understanding GoCommit.</p><h2 id="📖-documentation-index" tabindex="-1">📖 Documentation Index <a class="header-anchor" href="#📖-documentation-index" aria-label="Permalink to &quot;📖 Documentation Index&quot;">​</a></h2><h3 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h3><ul><li>Overview, installation, and basic usage</li><li><strong><a href="./INSTALL.html">Installation Guide</a></strong> - Detailed installation instructions</li></ul><h3 id="features-architecture" tabindex="-1">Features &amp; Architecture <a class="header-anchor" href="#features-architecture" aria-label="Permalink to &quot;Features &amp; Architecture&quot;">​</a></h3><ul><li><strong><a href="./JSON_SCHEMA_IMPLEMENTATION.html">JSON Schema Implementation</a></strong> - LangChain-style structured outputs for AI providers ⭐</li><li><strong><a href="./DELAYED_COMMIT_ARCHITECTURE.html">Delayed Commit Architecture</a></strong> - Schedule commits with smart time suggestions</li><li><strong><a href="./FLOW.html">Application Flow</a></strong> - Architecture and workflow diagrams</li><li><strong><a href="./REFACTORING_SUMMARY.html">Refactoring Summary</a></strong> - Codebase improvements and structure</li></ul><h3 id="configuration-integration" tabindex="-1">Configuration &amp; Integration <a class="header-anchor" href="#configuration-integration" aria-label="Permalink to &quot;Configuration &amp; Integration&quot;">​</a></h3><ul><li><strong><a href="./README_GITHUB_ACTIONS.html">GitHub Actions Integration</a></strong> - Automate commit generation in CI/CD</li><li><strong><a href="./README_LOGGING.html">Logging Guide</a></strong> - Debug and monitor your workflow</li><li><strong><a href="./README_LOGGING_CONFIG.html">Logging Configuration</a></strong> - Configure logging settings</li><li><strong><a href="./README_DELAYED_COMMIT.html">Delayed Commit Setup</a></strong> - Configure time-based commits</li></ul><h3 id="additional-resources" tabindex="-1">Additional Resources <a class="header-anchor" href="#additional-resources" aria-label="Permalink to &quot;Additional Resources&quot;">​</a></h3><ul><li><strong><a href="./PARSING_FIX_SUMMARY.html">Parsing Fix Summary</a></strong> - Technical details on parsing improvements</li><li><strong><a href="./REFACTORING_DESIGN.html">Refactoring Design</a></strong> - Design decisions and patterns</li><li><strong><a href="./gocommit-devto-blog.html">Dev.to Blog Post</a></strong> - Blog article about GoCommit</li></ul><h2 id="🌟-highlighted-features" tabindex="-1">🌟 Highlighted Features <a class="header-anchor" href="#🌟-highlighted-features" aria-label="Permalink to &quot;🌟 Highlighted Features&quot;">​</a></h2><h3 id="json-schema-structured-outputs" tabindex="-1">JSON Schema &amp; Structured Outputs <a class="header-anchor" href="#json-schema-structured-outputs" aria-label="Permalink to &quot;JSON Schema &amp; Structured Outputs&quot;">​</a></h3><p>GoCommit implements LangChain-style structured outputs for consistent JSON responses from AI providers. See <a href="./JSON_SCHEMA_IMPLEMENTATION.html">JSON_SCHEMA_IMPLEMENTATION.md</a> for details.</p><p><strong>Important</strong>: Only certain models support strict JSON schema validation:</p><ul><li>✅ OpenAI GPT-4o and newer</li><li>✅ Fireworks-provided models</li><li>⚠️ Other models rely on enhanced prompting + fallback parsing</li></ul><h3 id="multi-provider-support" tabindex="-1">Multi-Provider Support <a class="header-anchor" href="#multi-provider-support" aria-label="Permalink to &quot;Multi-Provider Support&quot;">​</a></h3><ul><li><strong>Gemini</strong> via Google AI API</li><li><strong>OpenRouter</strong> for access to Claude, GPT-4, Llama, and more</li></ul><h3 id="delayed-commits" tabindex="-1">Delayed Commits <a class="header-anchor" href="#delayed-commits" aria-label="Permalink to &quot;Delayed Commits&quot;">​</a></h3><p>Schedule commits for later with intelligent time suggestions based on your work hours.</p><h2 id="🚀-quick-links" tabindex="-1">🚀 Quick Links <a class="header-anchor" href="#🚀-quick-links" aria-label="Permalink to &quot;🚀 Quick Links&quot;">​</a></h2><ul><li><a href="https://github.com/thanhphuchuynh/gocommit" target="_blank" rel="noreferrer">GitHub Repository</a></li><li><a href="https://github.com/thanhphuchuynh/gocommit/issues" target="_blank" rel="noreferrer">Issue Tracker</a></li><li><a href="https://github.com/thanhphuchuynh/gocommit/releases" target="_blank" rel="noreferrer">Releases</a></li></ul><h2 id="📝-contributing" tabindex="-1">📝 Contributing <a class="header-anchor" href="#📝-contributing" aria-label="Permalink to &quot;📝 Contributing&quot;">​</a></h2><p>Contributions are welcome! Please see the main repository for contribution guidelines.</p><h2 id="📄-license" tabindex="-1">📄 License <a class="header-anchor" href="#📄-license" aria-label="Permalink to &quot;📄 License&quot;">​</a></h2><p>MIT License - see repository for details</p>',26)])])}const g=e(r,[["render",n]]);export{d as __pageData,g as default};
